package ae.rope;

import static org.junit.jupiter.api.Assertions.*;

import java.util.Random;
import org.junit.jupiter.api.Test;

class RopeSearchTest {

    @Test
    void literalHits() {
        Rope r = Rope.of("the quick brown fox jumps over the lazy dog");
        assertEquals(0, r.indexOf("the"));
        assertEquals(31, r.indexOf("the", 1));
        assertEquals(16, r.indexOf("fox"));
        assertEquals(-1, r.indexOf("cat"));
        assertEquals(-1, r.indexOf("the", 32));
        assertEquals(42, r.indexOf("g"));
    }

    @Test
    void emptyNeedleAndClamping() {
        Rope r = Rope.of("abc");
        assertEquals(0, r.indexOf(""));
        assertEquals(2, r.indexOf("", 2));
        assertEquals(3, r.indexOf("", 99), "empty needle clamps to length like String.indexOf");
        assertEquals(0, r.indexOf("", -5));
        assertEquals(0, r.indexOf("a", -5));
        assertEquals(-1, r.indexOf("abcd"));
        assertEquals(-1, Rope.empty().indexOf("a"));
        assertEquals(0, Rope.empty().indexOf(""));
    }

    @Test
    void needleSpanningLeafBoundariesAtEveryShift() {
        String needle = "NEEDLE";
        for (int pos = 0; pos <= 70; pos++) {
            String text = "x".repeat(pos) + needle + "y".repeat(70 - pos);
            Rope r = Rope.of(text);
            assertEquals(pos, r.indexOf(needle), "needle at " + pos);
            assertEquals(-1, r.indexOf(needle, pos + 1), "after needle at " + pos);
            assertEquals(pos, r.indexOf(needle, pos), "from == pos at " + pos);
        }
    }

    @Test
    void failureFunctionCases() {
        // 8 a's (indices 0-7) then b at 8: "aaab" occupies 5..8, found only if the matcher keeps its partial match
        assertEquals(5, Rope.of("aaaaaaaab" + "z".repeat(40)).indexOf("aaab"));
        assertEquals(2, Rope.of("ababababab".repeat(10)).indexOf("ababab", 1));
        assertEquals(98, Rope.of("ab".repeat(50) + "c").indexOf("abc"), "match is the very end of the text");
        assertEquals(-1, Rope.of("ab".repeat(50)).indexOf("abc"));
    }

    @Test
    void searchWorksOnEditedRopes() {
        Rope r = Rope.of("a".repeat(100)).insert(50, "NEEDLE").delete(0, 10).concat(Rope.of("tail"));
        String s = r.toString();
        assertEquals(s.indexOf("NEEDLE"), r.indexOf("NEEDLE"));
        assertEquals(s.indexOf("atail"), r.indexOf("atail"));
        assertEquals(40, r.indexOf("NEEDLE"));
    }

    @Test
    void randomDifferentialAgainstString() {
        Random rnd = new Random(7);
        for (int iter = 0; iter < 3000; iter++) {
            int n = rnd.nextInt(200);
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < n; i++) {
                sb.append((char) ('a' + rnd.nextInt(2)));
            }
            Rope r = Rope.of(sb);
            int m = 1 + rnd.nextInt(7);
            StringBuilder nb = new StringBuilder();
            for (int i = 0; i < m; i++) {
                nb.append((char) ('a' + rnd.nextInt(2)));
            }
            String needle = nb.toString();
            int from = rnd.nextInt(n + 5) - 2;
            assertEquals(sb.toString().indexOf(needle, from), r.indexOf(needle, from),
                    "text=" + sb + " needle=" + needle + " from=" + from);
        }
    }
}

package ae.rope;

import static org.junit.jupiter.api.Assertions.*;

import java.util.Random;
import org.junit.jupiter.api.Test;

/** Seeded random edit sequences against a StringBuilder oracle, with the invariant checker after every step. */
class RopeDifferentialTest {

    private static String randomText(Random rnd, int maxLen) {
        int n = rnd.nextInt(maxLen + 1);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            int c = rnd.nextInt(10);
            sb.append(c < 2 ? '\n' : (char) ('a' + c));
        }
        return sb.toString();
    }

    private static void assertSameLines(Rope r, String s, String ctx) {
        int newlines = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '\n') {
                newlines++;
            }
        }
        assertEquals(newlines + 1, r.lineCount(), ctx);
        int start = 0;
        for (int k = 0; k <= newlines; k++) {
            int nl = s.indexOf('\n', start);
            int end = nl < 0 ? s.length() : nl;
            assertEquals(start, r.lineStart(k), ctx + " lineStart " + k);
            assertEquals(s.substring(start, end), r.line(k), ctx + " line " + k);
            start = end + 1;
        }
    }

    @Test
    void randomEditsMatchStringBuilder() {
        int[] opCounts = new int[6];
        for (long seed = 1; seed <= 40; seed++) {
            Random rnd = new Random(seed);
            StringBuilder oracle = new StringBuilder(randomText(rnd, 150));
            Rope rope = Rope.of(oracle);
            for (int step = 0; step < 250; step++) {
                int len = oracle.length();
                int op = rnd.nextInt(6);
                if (len > 1500) {
                    op = 1; // keep sizes bounded: force a deletion
                }
                String ctx = "seed " + seed + " step " + step + " op " + op;
                switch (op) {
                    case 0 -> {
                        int at = rnd.nextInt(len + 1);
                        String ins = randomText(rnd, rnd.nextInt(5) == 0 ? 120 : 6);
                        rope = rope.insert(at, ins);
                        oracle.insert(at, ins);
                    }
                    case 1 -> {
                        int a = rnd.nextInt(len + 1);
                        int b = a + rnd.nextInt(Math.min(len - a, len > 1500 ? 600 : 60) + 1);
                        rope = rope.delete(a, b);
                        oracle.delete(a, b);
                    }
                    case 2 -> {
                        int a = rnd.nextInt(len + 1);
                        int b = a + rnd.nextInt(Math.min(len - a, 40) + 1);
                        String rep = randomText(rnd, 50);
                        rope = rope.replace(a, b, rep);
                        oracle.replace(a, b, rep);
                    }
                    case 3 -> {
                        Rope other = Rope.of(randomText(rnd, 90));
                        if (rnd.nextBoolean()) {
                            rope = rope.concat(other);
                            oracle.append(other.toString());
                        } else {
                            rope = other.concat(rope);
                            oracle.insert(0, other.toString());
                        }
                    }
                    case 4 -> { // rotate: split at i, swap halves
                        int at = rnd.nextInt(len + 1);
                        Rope.Split s = rope.split(at);
                        rope = s.right().concat(s.left());
                        String all = oracle.toString();
                        oracle = new StringBuilder(all.substring(at) + all.substring(0, at));
                    }
                    default -> { // keep a slice
                        int a = rnd.nextInt(len + 1);
                        int b = a + rnd.nextInt(len - a + 1);
                        if (b - a < 20 && len > 20) {
                            break;
                        }
                        rope = rope.subSequence(a, b);
                        oracle = new StringBuilder(oracle.substring(a, b));
                    }
                }
                opCounts[op]++;
                rope.check();
                assertEquals(oracle.toString(), rope.toString(), ctx);
                assertEquals(oracle.length(), rope.length(), ctx);
                if (step % 10 == 0) {
                    assertSameLines(rope, oracle.toString(), ctx);
                    if (oracle.length() > 0) {
                        int i = rnd.nextInt(oracle.length());
                        assertEquals(oracle.charAt(i), rope.charAt(i), ctx);
                    }
                    int off = rnd.nextInt(oracle.length() + 1);
                    String s = oracle.toString();
                    int line = (int) s.substring(0, off).chars().filter(c -> c == '\n').count();
                    assertEquals(line, rope.lineOf(off), ctx);
                    Rope.Position p = rope.positionOf(off);
                    assertEquals(off, rope.offsetOf(p.line(), p.column()), ctx);
                }
            }
        }
        for (int op = 0; op < 5; op++) {
            assertTrue(opCounts[op] >= 400, "operation " + op + " ran only " + opCounts[op] + " times");
        }
    }

    @Test
    void persistenceUnderRandomEdits() {
        Random rnd = new Random(99);
        String base = randomText(rnd, 400) + "tail".repeat(10);
        Rope[] versions = new Rope[60];
        String[] expected = new String[60];
        versions[0] = Rope.of(base);
        expected[0] = base;
        for (int v = 1; v < versions.length; v++) {
            int parent = rnd.nextInt(v);
            String p = expected[parent];
            int a = rnd.nextInt(p.length() + 1);
            int b = a + rnd.nextInt(Math.min(p.length() - a, 50) + 1);
            String ins = randomText(rnd, 30);
            versions[v] = versions[parent].replace(a, b, ins);
            expected[v] = p.substring(0, a) + ins + p.substring(b);
        }
        for (int v = 0; v < versions.length; v++) {
            versions[v].check();
            assertEquals(expected[v], versions[v].toString(), "version " + v);
        }
    }
}

package ae.rope;

import static org.junit.jupiter.api.Assertions.*;

import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;

class RopeLinesTest {

    // offsets: a0 b1 \n2 c3 d4 e5 \n6 \n7 f8   (length 9)
    static final String TEXT = "ab\ncde\n\nf";

    @Test
    void literalLineTable() {
        Rope r = Rope.of(TEXT);
        assertEquals(4, r.lineCount());
        assertEquals(0, r.lineStart(0));
        assertEquals(3, r.lineStart(1));
        assertEquals(7, r.lineStart(2));
        assertEquals(8, r.lineStart(3));
        assertEquals("ab", r.line(0));
        assertEquals("cde", r.line(1));
        assertEquals("", r.line(2));
        assertEquals("f", r.line(3));
    }

    @Test
    void lineOfAtEveryOffset() {
        Rope r = Rope.of(TEXT);
        int[] expected = {0, 0, 0, 1, 1, 1, 1, 2, 3, 3};
        for (int off = 0; off <= 9; off++) {
            assertEquals(expected[off], r.lineOf(off), "offset " + off);
        }
        assertThrows(IndexOutOfBoundsException.class, () -> r.lineOf(10));
        assertThrows(IndexOutOfBoundsException.class, () -> r.lineOf(-1));
    }

    @Test
    void positionsAndOffsets() {
        Rope r = Rope.of(TEXT);
        assertEquals(new Rope.Position(1, 2), r.positionOf(5));
        assertEquals(new Rope.Position(0, 2), r.positionOf(2));
        assertEquals(new Rope.Position(3, 1), r.positionOf(9));
        assertEquals(6, r.offsetOf(1, 3), "column == line length is the spot before the newline");
        assertEquals(9, r.offsetOf(3, 1));
        assertEquals(7, r.offsetOf(2, 0));
        assertThrows(IndexOutOfBoundsException.class, () -> r.offsetOf(1, 4));
        assertThrows(IndexOutOfBoundsException.class, () -> r.offsetOf(4, 0));
        assertThrows(IndexOutOfBoundsException.class, () -> r.offsetOf(0, -1));
        assertThrows(IndexOutOfBoundsException.class, () -> r.lineStart(4));
        assertThrows(IndexOutOfBoundsException.class, () -> r.line(-1));
    }

    @Test
    void emptyAndTrailingNewline() {
        Rope e = Rope.empty();
        assertEquals(1, e.lineCount());
        assertEquals("", e.line(0));
        assertEquals(0, e.lineStart(0));
        assertEquals(new Rope.Position(0, 0), e.positionOf(0));

        Rope t = Rope.of("x\n");
        assertEquals(2, t.lineCount());
        assertEquals("x", t.line(0));
        assertEquals("", t.line(1));
        assertEquals(2, t.lineStart(1));
        assertEquals(1, t.lineOf(2));
    }

    @Test
    void carriageReturnIsOrdinaryCharacter() {
        Rope r = Rope.of("a\r\nb");
        assertEquals(2, r.lineCount());
        assertEquals("a\r", r.line(0));
        assertEquals("b", r.line(1));
    }

    @Test
    void manyLinesAcrossManyLeavesMatchNaiveOracle() {
        StringBuilder sb = new StringBuilder();
        List<Integer> starts = new ArrayList<>();
        for (int i = 0; i < 200; i++) {
            starts.add(sb.length());
            sb.append("line ").append(i).append(i % 7 == 0 ? "" : "!".repeat(i % 5)).append('\n');
        }
        starts.add(sb.length()); // final empty line after the trailing newline
        Rope r = Rope.of(sb);
        assertEquals(201, r.lineCount());
        for (int k = 0; k < starts.size(); k++) {
            assertEquals(starts.get(k), r.lineStart(k), "start of line " + k);
            int end = k + 1 < starts.size() ? starts.get(k + 1) - 1 : sb.length();
            assertEquals(sb.substring(starts.get(k), end), r.line(k), "text of line " + k);
            assertEquals(k, r.lineOf(starts.get(k)), "lineOf start " + k);
        }
    }

    @Test
    void editsKeepLineIndexCurrent() {
        Rope r = Rope.of("one\ntwo\nthree");
        assertEquals(3, r.lineCount());
        Rope inserted = r.insert(3, "\nextra");
        assertEquals(4, inserted.lineCount());
        assertEquals("extra", inserted.line(1));
        Rope deleted = inserted.delete(3, 9); // removes "\nextra"
        assertEquals(r, deleted);
        assertEquals(3, deleted.lineCount());
        Rope joined = r.delete(3, 4); // remove the first newline
        assertEquals(2, joined.lineCount());
        assertEquals("onetwo", joined.line(0));
    }
}

package ae.rope;

import static org.junit.jupiter.api.Assertions.*;

import org.junit.jupiter.api.Test;

class RopeTest {

    /** 102 chars (20+20+20+20+22), longer than three leaves, so every op crosses leaf boundaries. */
    static final String LONG =
            "0123456789abcdefghij0123456789ABCDEFGHIJ0123456789klmnopqrst0123456789KLMNOPQRST0123456789uvwxyzUVWXYZ";

    @Test
    void emptyRope() {
        Rope e = Rope.empty();
        assertEquals(0, e.length());
        assertEquals("", e.toString());
        assertEquals(Rope.of(""), e);
        assertEquals(0, e.depth());
        e.check();
        assertThrows(IndexOutOfBoundsException.class, () -> e.charAt(0));
    }

    @Test
    void ofRoundTripsAndIndexesEveryChar() {
        Rope r = Rope.of(LONG);
        assertEquals(LONG.length(), r.length());
        assertEquals(LONG, r.toString());
        for (int i = 0; i < LONG.length(); i++) {
            assertEquals(LONG.charAt(i), r.charAt(i), "index " + i);
        }
        assertTrue(r.depth() >= 2);
        r.check();
    }

    @Test
    void charAtRejectsOutOfRange() {
        Rope r = Rope.of("abc");
        assertThrows(IndexOutOfBoundsException.class, () -> r.charAt(-1));
        assertThrows(IndexOutOfBoundsException.class, () -> r.charAt(3));
    }

    @Test
    void concatLiteral() {
        Rope r = Rope.of("hello ").concat(Rope.of("world"));
        assertEquals("hello world", r.toString());
        assertEquals(11, r.length());
        assertEquals("abc", Rope.empty().concat(Rope.of("abc")).toString());
        assertEquals("abc", Rope.of("abc").concat(Rope.empty()).toString());
    }

    @Test
    void concatOfTwoLongRopes() {
        Rope r = Rope.of(LONG).concat(Rope.of(LONG));
        assertEquals(LONG + LONG, r.toString());
        r.check();
    }

    @Test
    void insertAtStartMiddleEnd() {
        assertEquals("XYabc", Rope.of("abc").insert(0, "XY").toString());
        assertEquals("aXYbc", Rope.of("abc").insert(1, "XY").toString());
        assertEquals("abcXY", Rope.of("abc").insert(3, "XY").toString());
        String expected = LONG.substring(0, 33) + "<<>>" + LONG.substring(33);
        assertEquals(expected, Rope.of(LONG).insert(33, "<<>>").toString());
        assertThrows(IndexOutOfBoundsException.class, () -> Rope.of("abc").insert(4, "x"));
        assertThrows(IndexOutOfBoundsException.class, () -> Rope.of("abc").insert(-1, "x"));
    }

    @Test
    void deleteRanges() {
        assertEquals("ac", Rope.of("abc").delete(1, 2).toString());
        assertEquals("abc", Rope.of("abc").delete(1, 1).toString());
        assertEquals("", Rope.of("abc").delete(0, 3).toString());
        assertEquals(LONG.substring(0, 20) + LONG.substring(70), Rope.of(LONG).delete(20, 70).toString());
        assertThrows(IndexOutOfBoundsException.class, () -> Rope.of("abc").delete(2, 1));
        assertThrows(IndexOutOfBoundsException.class, () -> Rope.of("abc").delete(0, 4));
        assertThrows(IndexOutOfBoundsException.class, () -> Rope.of("abc").delete(-1, 1));
    }

    @Test
    void replaceRange() {
        assertEquals("aXc", Rope.of("abc").replace(1, 2, "X").toString());
        assertEquals("aXYZc", Rope.of("abc").replace(1, 2, "XYZ").toString());
        assertEquals("ac", Rope.of("abc").replace(1, 2, "").toString());
        assertEquals("abcd", Rope.of("abc").replace(3, 3, "d").toString());
    }

    @Test
    void splitAtEveryBoundary() {
        Rope r = Rope.of(LONG);
        for (int i = 0; i <= LONG.length(); i++) {
            Rope.Split s = r.split(i);
            assertEquals(LONG.substring(0, i), s.left().toString(), "left at " + i);
            assertEquals(LONG.substring(i), s.right().toString(), "right at " + i);
            s.left().check();
            s.right().check();
        }
        assertThrows(IndexOutOfBoundsException.class, () -> r.split(-1));
        assertThrows(IndexOutOfBoundsException.class, () -> r.split(LONG.length() + 1));
    }

    @Test
    void substringAndSubSequence() {
        Rope r = Rope.of(LONG);
        assertEquals(LONG.substring(31, 66), r.substring(31, 66));
        assertEquals("", r.substring(40, 40));
        CharSequence cs = r;
        assertEquals(LONG.substring(5, 50), cs.subSequence(5, 50).toString());
        assertTrue(r.subSequence(5, 50) instanceof Rope);
        assertThrows(IndexOutOfBoundsException.class, () -> r.substring(5, LONG.length() + 1));
        assertThrows(IndexOutOfBoundsException.class, () -> r.substring(6, 5));
    }

    @Test
    void equalsAndHashCodeIgnoreTreeShape() {
        Rope whole = Rope.of(LONG);
        Rope pieced = Rope.empty();
        for (int i = 0; i < LONG.length(); i += 7) {
            pieced = pieced.concat(Rope.of(LONG.substring(i, Math.min(LONG.length(), i + 7))));
        }
        assertEquals(whole, pieced);
        assertEquals(whole.hashCode(), pieced.hashCode());
        assertEquals(LONG.hashCode(), whole.hashCode());
        assertNotEquals(whole, pieced.insert(50, "x"));
        assertNotEquals(whole, Rope.of(LONG.substring(0, 99)));
        assertNotEquals(whole, LONG, "a Rope never equals a String");
        assertNotEquals(whole, null);
    }

    @Test
    void nullArgumentsAreRejected() {
        Rope r = Rope.of("abc");
        assertThrows(NullPointerException.class, () -> Rope.of(null));
        assertThrows(NullPointerException.class, () -> r.concat(null));
        assertThrows(NullPointerException.class, () -> r.insert(0, null));
        assertThrows(NullPointerException.class, () -> r.replace(0, 1, null));
        assertThrows(NullPointerException.class, () -> r.indexOf(null));
    }

    @Test
    void oldVersionsNeverChange() {
        Rope v0 = Rope.of(LONG);
        Rope v1 = v0.insert(50, "[INS]");
        Rope v2 = v1.delete(0, 10);
        Rope v3 = v2.replace(3, 60, "-");
        Rope v4 = v0.concat(v3);
        assertEquals(LONG, v0.toString());
        assertEquals(LONG.substring(0, 50) + "[INS]" + LONG.substring(50), v1.toString());
        assertEquals(v1.toString().substring(10), v2.toString());
        assertEquals(v2.toString().substring(0, 3) + "-" + v2.toString().substring(60), v3.toString());
        assertEquals(LONG + v3, v4.toString());
        for (Rope r : new Rope[] {v0, v1, v2, v3, v4}) {
            r.check();
        }
    }

    @Test
    void ofCharSequenceAcceptsStringBuilderAndRope() {
        assertEquals("xyz", Rope.of(new StringBuilder("xyz")).toString());
        Rope r = Rope.of(LONG);
        assertEquals(LONG, Rope.of(r).toString());
        assertEquals("ab" + LONG + "cd", Rope.of("ab").concat(r).concat(Rope.of("cd")).toString());
        assertEquals("a" + LONG + "bc", Rope.of("abc").insert(1, r).toString());
    }
}

package ae.rope;

import static org.junit.jupiter.api.Assertions.*;

import org.junit.jupiter.api.Test;

/** The invariant checker must itself be able to fail: feed it hand-built corrupt trees directly. */
class RopeCheckerTest {

    private static Rope.Leaf leaf(String s) {
        return new Rope.Leaf(s);
    }

    @Test
    void acceptsAValidHandBuiltTree() {
        Rope ok = new Rope(new Rope.Branch(new Rope.Branch(leaf("ab"), leaf("c\n")), leaf("d")));
        ok.check();
        assertEquals("abc\nd", ok.toString());
        assertEquals(2, ok.lineCount());
    }

    @Test
    void rejectsUnbalancedTree() {
        Rope.Node chain = new Rope.Branch(leaf("a"), new Rope.Branch(leaf("b"), new Rope.Branch(leaf("c"), leaf("d"))));
        IllegalStateException e = assertThrows(IllegalStateException.class, () -> new Rope(chain).check());
        assertTrue(e.getMessage().startsWith("unbalanced"), e.getMessage());
    }

    @Test
    void rejectsOversizeLeaf() {
        Rope big = new Rope(leaf("x".repeat(Rope.LEAF_MAX + 1)));
        IllegalStateException e = assertThrows(IllegalStateException.class, big::check);
        assertTrue(e.getMessage().startsWith("leaf too long"), e.getMessage());
    }

    @Test
    void rejectsEmptyNonRootLeaf() {
        Rope r = new Rope(new Rope.Branch(leaf(""), leaf("a")));
        IllegalStateException e = assertThrows(IllegalStateException.class, r::check);
        assertTrue(e.getMessage().startsWith("empty non-root leaf"), e.getMessage());
        new Rope(leaf("")).check(); // the empty root leaf is legal
    }
}

package ae.rope;

import static org.junit.jupiter.api.Assertions.*;

import java.time.Duration;
import java.util.Random;
import org.junit.jupiter.api.Test;

class RopeBalanceTest {

    /** AVL bound: height <= 1.4405 * log2(leaves + 2), plus slack of 2 for the leaf level. */
    private static void assertLogDepth(Rope r) {
        double bound = 1.45 * Math.log(r.leafCount() + 2) / Math.log(2) + 2;
        assertTrue(r.depth() <= bound, "depth " + r.depth() + " > " + bound + " for " + r.leafCount() + " leaves");
    }

    @Test
    void appendingSingleCharsStaysBalancedAndDense() {
        int n = 100_000;
        Rope r = Rope.empty();
        for (int i = 0; i < n; i++) {
            r = r.concat(Rope.of(String.valueOf((char) ('a' + i % 26))));
        }
        assertEquals(n, r.length());
        r.check();
        assertLogDepth(r);
        assertTrue(r.leafCount() <= n / Rope.LEAF_MAX + 2, "leaves " + r.leafCount());
        for (int i = 0; i < n; i += 997) {
            assertEquals((char) ('a' + i % 26), r.charAt(i));
        }
    }

    @Test
    void prependingSingleCharsStaysBalancedAndDense() {
        int n = 100_000;
        Rope r = Rope.empty();
        for (int i = 0; i < n; i++) {
            r = Rope.of(String.valueOf((char) ('a' + i % 26))).concat(r);
        }
        assertEquals(n, r.length());
        r.check();
        assertLogDepth(r);
        assertTrue(r.leafCount() <= n / Rope.LEAF_MAX + 2, "leaves " + r.leafCount());
        assertEquals((char) ('a' + (n - 1) % 26), r.charAt(0));
    }

    @Test
    void ofBuildsABalancedTreeOfFullLeaves() {
        for (int n : new int[] {0, 1, 32, 33, 64, 65, 1000, 4096, 4097}) {
            Rope r = Rope.of("z".repeat(n));
            r.check();
            int expectedLeaves = n == 0 ? 1 : (n + Rope.LEAF_MAX - 1) / Rope.LEAF_MAX; // empty rope = one empty leaf
            assertEquals(expectedLeaves, r.leafCount(), "leaf count for n=" + n);
            assertLogDepth(r);
        }
    }

    @Test
    void joiningVeryUnequalRopesStaysBalanced() {
        Rope big = Rope.of("q".repeat(200_000));
        Rope small = Rope.of("tiny");
        Rope a = big.concat(small);
        Rope b = small.concat(big);
        Rope c = small.concat(big).concat(small);
        for (Rope r : new Rope[] {a, b, c}) {
            r.check();
            assertLogDepth(r);
        }
        assertEquals(200_004, a.length());
        assertEquals('t', b.charAt(0));
        assertEquals('y', c.charAt(c.length() - 1));
    }

    @Test
    void randomEditsOnALargeRopeStayBalancedAndFast() {
        assertTimeoutPreemptively(Duration.ofSeconds(20), () -> {
            Random rnd = new Random(2024);
            Rope r = Rope.of("abcdefghij".repeat(100_000)); // 1,000,000 chars
            long expectedLen = r.length();
            for (int i = 0; i < 20_000; i++) {
                int len = r.length();
                if (rnd.nextBoolean()) {
                    int at = rnd.nextInt(len + 1);
                    r = r.insert(at, "XYZ");
                    expectedLen += 3;
                } else {
                    int a = rnd.nextInt(len - 5);
                    r = r.delete(a, a + 5);
                    expectedLen -= 5;
                }
            }
            assertEquals(expectedLen, r.length());
            r.check();
            assertLogDepth(r);
        });
    }
}
